urlset:
{% for page in site.pages %}
  {% unless page.sitemap == false %}
  
    {{ "https://hotsite.scoring.services" | append: page.url | replace: 'index.html', '' }}
    {% if page.lastmod %}
      {{ page.lastmod | date_to_xmlschema }}
    {% else %}
      {{ site.time | date_to_xmlschema }}
    {% endif %}
    weekly
    {% if page.url == "/" %}1.0{% else %}0.8{% endif %}
  
  {% endunless %}
{% endfor %}
